begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('c2000000-0000-4000-8000-000000000021','catalog-a@elifora.test'),('c2000000-0000-4000-8000-000000000022','catalog-b@elifora.test');
insert into public.organizations(id,name,slug,base_currency) values ('c2000000-0000-4000-8000-000000000001','Synthetic A','catalog-a','TRY'),('c2000000-0000-4000-8000-000000000002','Synthetic B','catalog-b','TRY');
insert into public.locations(id,organization_id,name,timezone) values ('c2000000-0000-4000-8000-000000000011','c2000000-0000-4000-8000-000000000001','Test A','Europe/Istanbul'),('c2000000-0000-4000-8000-000000000012','c2000000-0000-4000-8000-000000000002','Test B','Europe/Istanbul');
insert into public.salon_memberships(id,organization_id,location_id,user_id,role_code,status,joined_at) values
 ('c2000000-0000-4000-8000-000000000111','c2000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000011','c2000000-0000-4000-8000-000000000021','owner','active',now()),
 ('c2000000-0000-4000-8000-000000000112','c2000000-0000-4000-8000-000000000002','c2000000-0000-4000-8000-000000000012','c2000000-0000-4000-8000-000000000022','owner','active',now());
insert into app_private.catalog_operators(user_id) values ('c2000000-0000-4000-8000-000000000021');
select set_config('request.jwt.claim.sub','c2000000-0000-4000-8000-000000000021',true);
insert into public.brand_catalog_releases(id,series_id,version,scope,created_by) values ('c2000000-0000-4000-8000-000000000201','c2000000-0000-4000-8000-000000000202',1,'GLOBAL','c2000000-0000-4000-8000-000000000021');
insert into public.brand_catalog_releases(id,series_id,version,scope,organization_id,created_by) values
 ('c2000000-0000-4000-8000-000000000211','c2000000-0000-4000-8000-000000000212',1,'ORGANIZATION','c2000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000021');
insert into public.catalog_brands(id,catalog_id,display_name) values ('c2000000-0000-4000-8000-000000000301','c2000000-0000-4000-8000-000000000201','TEST_ONLY_FICTIONAL_BRAND');
insert into public.catalog_product_lines(id,catalog_id,brand_id,display_name) values ('c2000000-0000-4000-8000-000000000311','c2000000-0000-4000-8000-000000000201','c2000000-0000-4000-8000-000000000301','TEST_ONLY_LINE');
insert into public.catalog_products(id,series_id,version,catalog_id,brand_id,line_id,manufacturer_code,display_name,product_type,professional_category) values
 ('c2000000-0000-4000-8000-000000000321','c2000000-0000-4000-8000-000000000322',1,'c2000000-0000-4000-8000-000000000201','c2000000-0000-4000-8000-000000000301','c2000000-0000-4000-8000-000000000311','TEST_ONLY','Synthetic, no manufacturer claim','SHADE','TEST');
insert into public.catalog_technical_facts(catalog_id,product_id,key,source,verification_status,version) values ('c2000000-0000-4000-8000-000000000201','c2000000-0000-4000-8000-000000000321','neutral','UNKNOWN','UNVERIFIED',1);
select is((select value from public.catalog_technical_facts where key='neutral'),null::jsonb,'unknown pigment has no fabricated value');
select throws_ok($$update public.catalog_technical_facts set value='0'::jsonb where key='neutral'$$,'23514',null,'unknown cannot silently become numeric zero');
select throws_ok($$update public.catalog_products set verification_status='SALON_VERIFIED',verified_by=auth.uid(),verified_at=now()$$,'23514','VERIFICATION_SCOPE_INVALID','global catalog cannot claim salon verification');
select throws_ok($$select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000201','PUBLISHED',null,gen_random_uuid())$$,'23514','CATALOG_STATE_CONFLICT','publication cannot skip review');
select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000201','TECHNICAL_REVIEW',null,gen_random_uuid());
select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000201','GOLDEN_TEST',null,gen_random_uuid());
select throws_ok($$select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000201','APPROVED',null,gen_random_uuid())$$,'23514','GOLDEN_RECEIPT_REQUIRED','golden review receipt required');
select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000201','APPROVED','TEST_ONLY_GOLDEN_RECEIPT',gen_random_uuid());
select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000201','PUBLISHED',null,gen_random_uuid());
select throws_ok($$update public.catalog_products set display_name='changed'$$,'23514','IMMUTABLE_CATALOG_CONTENT','published product V1 cannot be rewritten');
select throws_ok($$delete from public.catalog_products$$,'23514','IMMUTABLE_CATALOG_CONTENT','published history cannot be deleted');
select is((select count(*) from public.brand_catalog_audit where action='catalog.version_published'),1::bigint,'publication audit exists');
select ok((select count(*) from public.brand_catalog_audit where action='catalog.technical_value_changed')>0,'technical mutation audit exists');
select ok((public.brand_catalog_packet('c2000000-0000-4000-8000-000000000201')#>>'{release,versionFingerprint}') ~ '^[a-f0-9]{64}$','catalog version has canonical fingerprint');
create temporary table historical_packet as select public.brand_catalog_packet('c2000000-0000-4000-8000-000000000201') as value;
grant select on historical_packet to authenticated;
update app_private.catalog_operators set active=false;
set local role authenticated;
select is((select count(*) from public.brand_catalog_releases),2::bigint,'member sees published global and own custom catalog');
select is((select count(*) from public.catalog_products),1::bigint,'global product readable by an intended authenticated member');
select throws_ok($$insert into public.catalog_products default values$$,'42501',null,'direct catalog writes denied');
select throws_ok($$update public.catalog_products set verification_status='ELIFORA_VERIFIED'$$,'42501',null,'client verification forgery denied');
select throws_ok($$insert into app_private.catalog_operators(user_id) values(auth.uid())$$,'42501',null,'client cannot appoint central operator');
select throws_ok($$delete from public.brand_catalog_audit$$,'42501',null,'catalog audit immutable to application role');
select throws_ok($$select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000201','RETIRED',null,gen_random_uuid())$$,'42501','FORBIDDEN','salon owner cannot govern central catalog');
select throws_ok($$insert into public.brand_recipe_drafts default values$$,'42501',null,'client cannot forge brand-ready result');
select throws_ok($$update public.brand_recipe_drafts set executable=true$$,'42501',null,'application cannot enable executable chemistry');
select ok(not has_function_privilege('anon','public.brand_recipe_store(uuid,uuid,text,text,uuid)','EXECUTE'),'anonymous cannot invoke signed store');
select ok(not has_function_privilege('service_role','public.brand_recipe_store(uuid,uuid,text,text,uuid)','EXECUTE'),'service role cannot generate recipes');
select is(public.brand_recipe_store('c2000000-0000-4000-8000-000000000111','c2000000-0000-4000-8000-000000000011','{}',repeat('0',64),gen_random_uuid())->>'code','COLOR_PLAN_SIGNATURE_INVALID','unsigned engine payload denied');
select set_config('request.jwt.claim.sub','c2000000-0000-4000-8000-000000000022',true);
select is((select count(*) from public.brand_catalog_releases),1::bigint,'other organization sees global only');
select is(public.brand_catalog_packet('c2000000-0000-4000-8000-000000000211'),null::jsonb,'cross tenant custom catalog concealed');
select throws_ok($$select public.brand_catalog_transition('c2000000-0000-4000-8000-000000000211','TECHNICAL_REVIEW',null,gen_random_uuid())$$,'42501','FORBIDDEN','cross tenant transition rejected');
reset role;
update public.salon_memberships set status='revoked',revoked_at=now() where user_id='c2000000-0000-4000-8000-000000000022';
set local role authenticated;
select is((select count(*) from public.brand_catalog_releases),0::bigint,'revoked member loses global access immediately');
reset role;
set local role anon;
select throws_ok($$select * from public.brand_catalog_releases$$,'42501',null,'anonymous catalog read denied');
select throws_ok($$select public.brand_catalog_packet('c2000000-0000-4000-8000-000000000201')$$,'42501',null,'anonymous packet read denied');
reset role;
select set_config('request.jwt.claim.sub','c2000000-0000-4000-8000-000000000021',true);
update app_private.catalog_operators set active=true;
insert into public.brand_catalog_releases(id,series_id,version,previous_id,scope,created_by) values ('c2000000-0000-4000-8000-000000000203','c2000000-0000-4000-8000-000000000202',2,'c2000000-0000-4000-8000-000000000201','GLOBAL',auth.uid());
select is(public.brand_catalog_packet('c2000000-0000-4000-8000-000000000201'),(select value from historical_packet),'new release preserves complete historical V1 packet');
select is((select version from public.brand_catalog_releases where id='c2000000-0000-4000-8000-000000000203'),2,'forward catalog version accepted');
select throws_ok($$insert into public.brand_catalog_releases(series_id,version,previous_id,scope,created_by) values('c2000000-0000-4000-8000-000000000202',4,'c2000000-0000-4000-8000-000000000203','GLOBAL',auth.uid())$$,'23514','CATALOG_VERSION_CONFLICT','catalog version gap rejected');
select * from finish();
rollback;
